package com.airscreen.networking

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

/** Vectors generated by the Python sender (shared/test-data/crypto_vectors.json). Both sides must agree. */
class CryptoTest {
    private val ns = Crypto.unhex("01010101010101010101010101010101")
    private val nr = Crypto.unhex("02020202020202020202020202020202")
    private val secret = "ABCDEFGHJKLMNPQR".toByteArray()

    @Test fun clientProof() = assertEquals(
        "9cd6c2b0f2fb4cb6df6fca3585985f6c03cbd88a37a6f1ac32048bf18b89deb2",
        Crypto.hex(Crypto.clientProof(secret, ns, nr, "dev1")))

    @Test fun serverProof() = assertEquals(
        "e783e16e9bf464acce65cfab9c3774a6981da21afbaa12e560548c1ee9c1f83d",
        Crypto.hex(Crypto.serverProof(secret, ns, nr)))

    @Test fun deviceKey() = assertEquals(
        "aa6a23df96dd4158a3df113dab6d38ca664319585b07470671ec5709db3a3724",
        Crypto.hex(Crypto.deviceKey(secret, ns, nr)))

    @Test fun sessionKeyAndGcm() {
        val key = Crypto.sessionKey(secret, ns, nr)
        assertEquals("6ad6927b32fc6ebcc39e1049c7a99fb338cb3cc44306ffd90ca39582b0a78db1", Crypto.hex(key))
        val sealed = Crypto.unhex("85d964cf053a612d456149e5ddb951cc87db78c73cc698044df0303e6b2808")
        val plain = Crypto.MediaCipher(key).open(5, sealed, "header-bytes".toByteArray())
        assertArrayEquals("hello airscreen".toByteArray(), plain)
    }

    @Test(expected = javax.crypto.AEADBadTagException::class)
    fun tamperedDataRejected() {
        val key = Crypto.sessionKey(secret, ns, nr)
        val sealed = Crypto.unhex("85d964cf053a612d456149e5ddb951cc87db78c73cc698044df0303e6b2808")
        sealed[0] = (sealed[0].toInt() xor 1).toByte()
        Crypto.MediaCipher(key).open(5, sealed, "header-bytes".toByteArray())
    }
}
